import { useAudioPlayer } from "expo-audio";
import { Pressable, StyleSheet } from "react-native";

import { ThemedText } from "@/components/ThemedText";
import { Colors } from "@/constants/Colors";
import type { Pitch } from "@/core";

/**
 * Bundled samples, one per tonic, indexed by semitone above C. They ship inside the app,
 * so the Pitch sounds offline. Generated by scripts/generate-pitch-samples.js.
 */
const SAMPLES = [
    require("@/assets/audio/pitch/00-C.wav"),
    require("@/assets/audio/pitch/01-Cs-Db.wav"),
    require("@/assets/audio/pitch/02-D.wav"),
    require("@/assets/audio/pitch/03-Ds-Eb.wav"),
    require("@/assets/audio/pitch/04-E.wav"),
    require("@/assets/audio/pitch/05-F.wav"),
    require("@/assets/audio/pitch/06-Fs-Gb.wav"),
    require("@/assets/audio/pitch/07-G.wav"),
    require("@/assets/audio/pitch/08-Gs-Ab.wav"),
    require("@/assets/audio/pitch/09-A.wav"),
    require("@/assets/audio/pitch/10-As-Bb.wav"),
    require("@/assets/audio/pitch/11-B.wav"),
];

/** Sounds the tonic of a Tag's Key once, like a pitch pipe. It can be pressed again at any time. */
export function PitchButton({ pitch }: { pitch: Pitch }) {
    const player = useAudioPlayer(SAMPLES[pitch.semitone]);
    const label = `${pitch.tonic} ${pitch.tonality}`;

    const sound = async () => {
        // Start from the beginning, whether the note has finished or is still sounding.
        try {
            await player.seekTo(0);
        } catch (error) {
            // Still sound the note: a failed rewind shouldn't make the press do nothing.
            console.error(error);
        }
        player.play();
    };

    return (
        <Pressable
            style={({ pressed }) => [styles.button, pressed && styles.pressed]}
            onPress={sound}
            accessibilityRole="button"
            accessibilityLabel={`Pitch: ${label}`}
        >
            <ThemedText style={styles.text}>♪ Pitch · {label}</ThemedText>
        </Pressable>
    );
}

const styles = StyleSheet.create({
    button: {
        alignSelf: "flex-start",
        backgroundColor: Colors.light.tint,
        borderRadius: 8,
        paddingHorizontal: 16,
        paddingVertical: 8,
    },
    pressed: {
        opacity: 0.7,
    },
    text: {
        color: "#fff",
    },
});
